import re, zlib, base64, sys

def extract_pdf_text(path):
    data = open(path,'rb').read()
    # find all stream...endstream
    chunks = re.findall(rb'stream\r?\n(.*?)endstream', data, re.S)
    out = []
    for ch in chunks:
        ch = ch.strip(b'\r\n')
        # try ascii85
        try:
            decoded = base64.a85decode(ch, adobe=True)
            try:
                decoded = zlib.decompress(decoded)
            except Exception:
                pass
            out.append(decoded)
        except Exception:
            # try raw flate
            try:
                out.append(zlib.decompress(ch))
            except Exception:
                pass
    return b'\n'.join(out)

if __name__=='__main__':
    t = extract_pdf_text(sys.argv[1])
    print(t.decode('latin-1'))
